const searchTemplates = [
  {
    key: 'ai-n8n',
    target_resume: 'ai_automation',
    text: 'n8n',
    search_field: 'description',
  },
  {
    key: 'ai-automation',
    target_resume: 'ai_automation',
    text: 'инженер по автоматизации',
    search_field: 'name',
  },
  {
    key: 'ai-integration-engineer',
    target_resume: 'ai_automation',
    text: 'инженер по интеграциям',
    search_field: 'name',
  },
  {
    key: 'ai-integration-specialist',
    target_resume: 'ai_automation',
    text: 'специалист по интеграциям',
    search_field: 'name',
  },
  {
    key: 'ai-business-process-automation',
    target_resume: 'ai_automation',
    text: 'автоматизация бизнес-процессов',
    search_field: 'description',
  },
  {
    key: 'ai-llm',
    target_resume: 'ai_automation',
    text: 'LLM',
    search_field: 'description',
  },
  {
    key: 'it-engineer',
    target_resume: 'it_infrastructure',
    text: 'IT-инженер',
    search_field: 'name',
  },
  {
    key: 'it-system-administrator',
    target_resume: 'it_infrastructure',
    text: 'системный администратор',
    search_field: 'name',
  },
  {
    key: 'it-system-engineer',
    target_resume: 'it_infrastructure',
    text: 'системный инженер',
    search_field: 'name',
  },
  {
    key: 'it-support-engineer',
    target_resume: 'it_infrastructure',
    text: 'инженер технической поддержки',
    search_field: 'name',
  },
  {
    key: 'it-support-specialist',
    target_resume: 'it_infrastructure',
    text: 'специалист технической поддержки',
    search_field: 'name',
  },
  {
    key: 'it-network-engineer',
    target_resume: 'it_infrastructure',
    text: 'сетевой инженер',
    search_field: 'name',
  },
];

const scopes = [
  {
    key: 'spb',
    area: '2',
    schedule: '',
  },
  {
    key: 'remote',
    area: '113',
    schedule: 'remote',
  },
];

const pagesPerSearch = 4;
const output = [];

for (const template of searchTemplates) {
  for (const scope of scopes) {
    for (let page = 0; page < pagesPerSearch; page += 1) {
      const queryParams = {
        text: template.text,
        area: scope.area,
        order_by: 'publication_time',
        page: String(page),
      };

      if (scope.schedule) {
        queryParams.schedule = scope.schedule;
      }

      if (template.search_field) {
        queryParams.search_field = template.search_field;
      }

      const queryString = Object.entries(queryParams)
        .map(([key, value]) => {
          return `${encodeURIComponent(key)}=${encodeURIComponent(
            String(value)
          )}`;
        })
        .join('&');

      output.push({
        json: {
          source_query: `${template.key}-${scope.key}`,
          target_resume: template.target_resume,
          search_text: template.text,
          area: scope.area,
          schedule: scope.schedule,
          page,
          url: `https://hh.ru/search/vacancy?${queryString}`,
        },
      });
    }
  }
}

return output;

const responseItems = $input.all();
const sourceItems = $("Generate Search URLs").all();

if (responseItems.length !== sourceItems.length) {
  throw new Error(
    `Search response count mismatch: ${responseItems.length} responses for ${sourceItems.length} configurations`
  );
}

const vacancies = new Map();
const searchErrors = [];

for (let index = 0; index < responseItems.length; index += 1) {
  const response = responseItems[index].json;
  const source = sourceItems[index]?.json;

  if (!source) {
    searchErrors.push(`Missing source configuration for item ${index}`);
    continue;
  }

  const htmlCandidates = [
    typeof response === "string" ? response : null,
    response?.data,
    response?.body,
    response?.response,
  ];

  const html = htmlCandidates.find(
    (value) => typeof value === "string"
  );

  if (!html) {
    searchErrors.push(
      `${source.source_query}: HTTP Request did not return an HTML string`
    );
    continue;
  }

  const normalizedHtml = html.replace(/&amp;/g, "&");
  const pattern = /href="([^"]*\/vacancy\/(\d+)[^"]*)"/g;

  let foundForQuery = 0;

  for (const match of normalizedHtml.matchAll(pattern)) {
    const vacancyId = match[2];
    const canonicalUrl = `https://hh.ru/vacancy/${vacancyId}`;

    if (!vacancies.has(vacancyId)) {
      vacancies.set(vacancyId, {
        vacancy_id: vacancyId,
        url: canonicalUrl,
        source_queries: [],
        target_resumes: [],
        search_texts: [],
        search_pages: [],
      });
    }

    const vacancy = vacancies.get(vacancyId);

    if (!vacancy.source_queries.includes(source.source_query)) {
      vacancy.source_queries.push(source.source_query);
    }

    if (
      source.target_resume &&
      !vacancy.target_resumes.includes(source.target_resume)
    ) {
      vacancy.target_resumes.push(source.target_resume);
    }

    if (!vacancy.search_texts.includes(source.search_text)) {
      vacancy.search_texts.push(source.search_text);
    }

    const pageReference = `${source.source_query}:${source.page}`;

    if (!vacancy.search_pages.includes(pageReference)) {
      vacancy.search_pages.push(pageReference);
    }

    foundForQuery += 1;
  }

  if (foundForQuery === 0) {
    searchErrors.push(
      `${source.source_query}: no vacancy links found`
    );
  }
}

if (vacancies.size === 0) {
  const details = searchErrors.length
    ? ` Details: ${searchErrors.join("; ")}`
    : "";

  throw new Error(`No vacancy links found.${details}`);
}

return Array.from(vacancies.values())
  .map((vacancy) => ({
    json: {
      vacancy_id: vacancy.vacancy_id,
      url: vacancy.url,
      source_query: vacancy.source_queries.join(","),
      target_resume_hint: vacancy.target_resumes.join(","),
      search_text: vacancy.search_texts.join(" | "),
      search_page: vacancy.search_pages.join(","),
      search_warnings: searchErrors.join("; "),
    },
  }));

const response = $json;
const htmlCandidates = [
  typeof response === "string" ? response : null,
  response.data,
  response.body,
  response.response,
];
const html = htmlCandidates.find((value) => typeof value === "string");

if (!html) {
  throw new Error("Vacancy request did not return an HTML string");
}

const sourceItems = $("Limit New Vacancies").all();
const source = sourceItems[$itemIndex]?.json;

if (!source) {
  throw new Error(`Source vacancy is missing for item ${$itemIndex}`);
}

function decodeEntities(value) {
  return String(value || "")
    .replace(/&nbsp;/g, " ")
    .replace(/&amp;/g, "&")
    .replace(/&quot;/g, String.fromCharCode(34))
    .replace(/&#39;/g, String.fromCharCode(39))
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">");
}

function cleanHtml(value) {
  return decodeEntities(
    String(value || "")
      .replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi, " ")
      .replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi, " ")
      .replace(/<br\s*\/?>/gi, "\n")
      .replace(/<\/p>/gi, "\n")
      .replace(/<\/li>/gi, "\n")
      .replace(/<[^>]+>/g, " ")
  )
    .replace(/[ \t]+/g, " ")
    .replace(/ *\n */g, "\n")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
}

function firstMatch(pattern) {
  const match = html.match(pattern);
  return match ? cleanHtml(match[1]) : "";
}

const title =
  firstMatch(
    /<h1[^>]+data-qa="vacancy-title"[^>]*>([\s\S]*?)<\/h1>/i
  ) ||
  firstMatch(
    /<title[^>]*>([\s\S]*?)<\/title>/i
  );

const seoDescription = firstMatch(/<meta[^>]+name="description"[^>]+content="([^"]*)"/i);
const company = firstMatch(/<[^>]+data-qa="vacancy-company-name"[^>]*>([\s\S]*?)<\/[^>]+>/i);

const descriptionText = firstMatch(
  /<div[^>]*data-qa="vacancy-description"[^>]*>([\s\S]*?)<\/div>/i
).slice(0, 20000);

const pageText = cleanHtml(html);

const workFormatMatch = pageText.match(
  /Формат работы:\s*(удал[её]нно или гибрид|гибрид|удал[её]нно|на месте работодателя|разъездной)/i
);

const workFormatRaw = String(workFormatMatch?.[1] || "")
  .replace(/\u00a0/g, " ")
  .replace(/\s+/g, " ")
  .trim();

if (!title) {
  throw new Error("Vacancy title was not extracted");
}

return {
  json: {
    vacancy_id: source.vacancy_id,
    url: source.url,
    source_query: source.source_query,
    title,
    company,
    seo_description: seoDescription,
    work_format_raw: workFormatRaw,
    description_text: descriptionText,
    description_found: descriptionText.length > 100,
    description_length: descriptionText.length,
    fetched_at: new Date().toISOString(),
  },
};

const vacancy = $json;
const now = new Date().toISOString();
const seo = String(vacancy.seo_description || "");

function normalizeText(value) {
  return String(value || "")
    .replace(/\u00a0/g, " ")
    .replace(/[ \t]+/g, " ")
    .replace(/\s+([,.;:!?])/g, "$1")
    .trim();
}

function toPublishedIso(value) {
  const match = String(value || "").match(
    /Дата публикации:\s*(\d{2})\.(\d{2})\.(\d{4})/
  );

  if (!match) return "";

  const [, day, month, year] = match;
  return `${year}-${month}-${day}T00:00:00.000Z`;
}

function createContentHash(value) {
  const text = String(value || "");
  let hash = 2166136261;

  for (let index = 0; index < text.length; index += 1) {
    hash ^= text.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }

  return (hash >>> 0).toString(16).padStart(8, "0");
}

const salaryLocationMatch = seo.match(
  /Зарплата:\s*(.*?)\.\s*(.*?)\.\s*Требуемый опыт:/i
);

const experienceMatch = seo.match(
  /Требуемый опыт:\s*(.*?)\.\s*Занятость:/i
);

const descriptionText = normalizeText(vacancy.description_text);

function normalizeWorkFormat(rawValue, descriptionValue) {
  const raw = normalizeText(rawValue).toLowerCase();
  const description = normalizeText(descriptionValue).toLowerCase();

  if (/удал[её]нно или гибрид|гибрид/.test(raw)) {
    return "hybrid";
  }

  if (/удал[её]нно|дистанционно/.test(raw)) {
    return "remote";
  }

  if (/на месте работодателя|офис/.test(raw)) {
    return "office";
  }

  if (/разъезд/.test(raw)) {
    return "field";
  }

  if (
    /работа только в офисе|удал[её]нного формата нет|удал[её]нной работы нет/.test(
      description
    )
  ) {
    return "office";
  }

  if (
    /разъездн(?:ая|ой|ую)\s+работ|выезжать к клиентам|выездн(?:ая|ой|ые)\s+работ/.test(
      description
    )
  ) {
    return "field";
  }

  if (/гибридн(?:ая|ый|ое|ом)\s+(?:работа|формат)/.test(description)) {
    return "hybrid";
  }

  if (
    /удал[её]нн(?:ая|ый|ое|ой)\s+(?:работа|формат)|работа\s+удал[её]нно/.test(
      description
    )
  ) {
    return "remote";
  }

  return "unspecified";
}

const workFormat = normalizeWorkFormat(
  vacancy.work_format_raw,
  descriptionText
);

return {
  json: {
    vacancy_id: String(vacancy.vacancy_id),
    url: String(vacancy.url),
    title: normalizeText(vacancy.title),
    company: normalizeText(vacancy.company),
    salary: normalizeText(salaryLocationMatch?.[1]),
    location: normalizeText(salaryLocationMatch?.[2]),
    work_format: workFormat,
    experience: normalizeText(experienceMatch?.[1]),
    published_at: toPublishedIso(seo),
    first_seen_at: now,
    updated_at: now,
    source_query: String(vacancy.source_query || ""),
    description_text: descriptionText,
    content_hash: createContentHash(descriptionText),
    status: vacancy.description_found ? "found" : "parse_failed",
    filter_reason: "",
    score: 0,
    recommended_resume: "",
    analysis_json: "",
    cover_letter: "",
    telegram_message_id: "",
    last_error: vacancy.description_found
      ? ""
      : "Vacancy description was not extracted",
  },
};

const vacancy = { ...$json };

const title = String(vacancy.title || "")
  .replace(/\s+/g, " ")
  .trim();

const description = String(vacancy.description_text || "")
  .replace(/\s+/g, " ")
  .trim();

const reasons = [];

const location = String(vacancy.location || "")
  .replace(/\s+/g, " ")
  .trim()
  .toLowerCase();

const workFormat = String(vacancy.work_format || "")
  .trim()
  .toLowerCase();

const isLocalLocation =
  /санкт-петербург|мурино/.test(location);

const requiresLocalPresence = [
  "office",
  "hybrid",
  "field",
].includes(workFormat);

if (requiresLocalPresence && !isLocalLocation) {
  reasons.push("location_format_mismatch");
}

const descriptionLower = description.toLowerCase();

const explicitlyRemote =
  /полностью удал[её]нн|удал[её]нная работа|удал[её]нный формат|работа удал[её]нно/.test(
    descriptionLower
  );

const nonLocalOfficeMention =
  (
    /офис.{0,160}(?:москв|метро\s+1905|проспект вернадского)/i.test(
      descriptionLower
    ) ||
    /(?:москв|метро\s+1905|проспект вернадского).{0,160}офис/i.test(
      descriptionLower
    )
  ) &&
  !explicitlyRemote;

if (nonLocalOfficeMention) {
  reasons.push("location_format_mismatch");
}

const titleBlockers = [
  {
    code: "sales_role",
    pattern:
      /менеджер по продажам|руководитель продаж|sales manager|account manager|аккаунт-менеджер|business development|менеджер по работе с партнерами|менеджер по работе с клиентами/i,
  },
  {
    code: "creative_marketing_role",
    pattern:
      /ai creator|creative producer|креативный продюсер|продюсер креативов|paid social/i,
  },
  {
    code: "supply_chain_analytics_role",
    pattern:
      /аналитик закупок|supply chain data analyst|demand planning|inventory analyst/i,
  },
  {
    code: "technical_leadership_role",
    pattern:
      /техлид|tech lead|technical lead/i,
  },
  {
    code: "marketing_seo_role",
    pattern:
      /маркетолог|media buyer|медиабайер|контекстн(?:ая|ой)\s+реклам|seo[- /]|seo специалист|seo-специалист|seo developer|community manager|контент[- ]менеджер|руководитель.*\bpr\b/i,
  },
  {
    code: "assistant_role",
    pattern:
      /ассистент руководителя|помощник руководителя|бизнес-ассистент|личный ассистент/i,
  },
  {
    code: "project_product_role",
    pattern:
      /project manager|product manager|project\/product manager|руководитель проектов|менеджер проектов|проджект[- ]менеджер|продакт[- ]менеджер/i,
  },
  {
    code: "recruiting_role",
    pattern:
      /рекрутер|hr[- ]менеджер|hr manager|менеджер по персоналу|специалист по подбору персонала/i,
  },
  {
    code: "ml_ds_role",
    pattern:
      /machine learning|\bml[- /]|ml engineer|ml-инженер|ml\/ds|data scientist|data science|ds инженер|инженер машинного обучения|разработчик искусственного интеллекта|разработчик рекомендательной системы/i,
  },
  {
    code: "industrial_automation_role",
    pattern:
      /асу\s*тп|асутп|кипиа|кип и а|\bplc\b|плк|\bscada\b|автоматизаци[яи] технологических процессов|автоматизаци[яи] производства|инженер пнр/i,
  },
  {
    code: "industrial_engineering_role",
    pattern:
      /инженер-технолог|ведущий инженер-технолог|инженер-конструктор|инженер-схемотехник|инженер-испытатель|монтажник рэа|электрооборудовани[юя].*автоматизаци|инженер-проектировщик.*эом|инженер производственного склада/i,
  },
  {
    code: "one_c_development_role",
    pattern:
      /программист\s*1с|разработчик\s*1с|1с[- ]разработчик/i,
  },
  {
    code: "non_it_role",
    pattern:
      /курьер|водитель|кладовщик|комплектовщик|повар|продавец-консультант|ведущий юрист|менеджер по логистике|методолог образовательных программ|эксплуатаци[яи] и ремонт.*помещени/i,
  },
  {
    code: "computer_club_role",
    pattern:
      /администратор компьютерного клуба/i,
  },
  {
    code: "traffic_arbitrage_role",
    pattern:
      /traffic arbitrage|traffic buyer|арбитраж трафика/i,
  },
];

for (const blocker of titleBlockers) {
  if (blocker.pattern.test(title)) {
    reasons.push(blocker.code);
  }
}

const pureDevelopmentSignals = [
  /коммерческ\w*\s+разработк\w*\s+от\s+\d+\s+лет/i,
  /frontend|backend/i,
  /react|vue|next\.?js|nuxt\.?js/i,
  /typescript|node\.?js/i,
  /bigquery|postgresql|redis|dwh/i,
  /автотест/i,
  /векторн\w*\s+поиск|векторн\w*\s+баз/i,
];

const pureDevelopmentSignalCount =
  pureDevelopmentSignals.filter((pattern) =>
    pattern.test(description)
  ).length;

if (!vacancy.vacancy_id) {
  reasons.push("missing_vacancy_id");
}

if (!vacancy.url) {
  reasons.push("missing_url");
}

if (!title) {
  reasons.push("missing_title");
}

if (!description || description.length < 200) {
  reasons.push("insufficient_description");
}

const industrialFilterText = [
  vacancy.title,
  vacancy.description_text,
]
  .map((value) => String(value || ''))
  .join(' ')
  .toLowerCase()
  .replace(/\s+/g, ' ')
  .trim();

const directIndustrialPatterns = [
  /(?:^|[^а-яё])асу\s*тп(?:$|[^а-яё])/i,
  /(?:^|[^а-яё])асутп(?:$|[^а-яё])/i,
  /(?:^|[^а-яё])кип\s*(?:и\s*)?а(?:$|[^а-яё])/i,
  /автоматизаци[яи]\s+технологическ(?:их|ого)\s+процесс/i,
];

const contextualIndustrialPatterns = [
  /\bscada\b/i,
  /\bplc\b/i,
  /(?:^|[^а-яё])плк(?:$|[^а-яё])/i,
  /электрическ(?:ая|ие|их|ой|ую)\s+схем/i,
  /щит(?:ы|ов|а|ами)?\s+управления/i,
  /промышленн(?:ая|ой|ую|ые|ых)\s+автоматизаци/i,
  /промышленн(?:ый|ые|ых|ого)\s+контроллер/i,
  /компрессорн(?:ая|ые|ых|ой)\s+(?:станци|установ)/i,
  /холодильн(?:ое|ого|ым|ая|ой)\s+оборудован/i,
  /компас-?3d/i,
  /\beplan\b/i,
  /пусконаладочн(?:ые|ых|ая|ой)\s+работ/i,
  /проектировани[ея].{0,80}электрооборудован/i,
  /проектн(?:ая|ой)\s+документаци.{0,80}электро/i,
];

const hasDirectIndustrialSignal = directIndustrialPatterns.some(
  (pattern) => pattern.test(industrialFilterText)
);

const contextualIndustrialSignalCount =
  contextualIndustrialPatterns.filter(
    (pattern) => pattern.test(industrialFilterText)
  ).length;

if (
  hasDirectIndustrialSignal ||
  contextualIndustrialSignalCount >= 2
) {
  reasons.push('industrial_automation_role');
}

const parseFailureReasons = new Set([
  "missing_vacancy_id",
  "missing_url",
  "missing_title",
  "insufficient_description",
]);

const hasParseFailure = reasons.some((reason) =>
  parseFailureReasons.has(reason)
);

if (hasParseFailure) {
  vacancy.status = "parse_failed";
} else if (reasons.length > 0) {
  vacancy.status = "filtered";
} else {
  vacancy.status = "found";
}

vacancy.filter_reason = reasons.join(",");
vacancy.updated_at = new Date().toISOString();

if (vacancy.status === "parse_failed" && !vacancy.last_error) {
  vacancy.last_error =
    "Required vacancy data is missing or incomplete";
}

return {
  json: vacancy,
};
